using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
using LWS.TruckHockey;
namespace LWS.TruckSports.Editor {
public static class SportsArenaAuthoring {
 public static void UpgradeHockey(){var scene=EditorSceneManager.OpenScene(LWS.TruckHockey.Editor.HockeyAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<HockeyMatch>();Upgrade(m);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
 public static void Upgrade(HockeyMatch m){var ice=GameObject.Find("Ice");float ratio=34.8f/ice.transform.localScale.x;foreach(var root in m.gameObject.scene.GetRootGameObjects()){if(root==m.gameObject||root.GetComponentInChildren<Rigidbody>()!=null||root.GetComponentInChildren<Canvas>()!=null||root.GetComponentInChildren<Camera>()!=null||root.GetComponent<Light>()!=null)continue;var line=root.GetComponent<LineRenderer>();if(line!=null&&line.useWorldSpace){for(int i=0;i<line.positionCount;i++){var p=line.GetPosition(i);p.x*=ratio;p.z*=ratio;line.SetPosition(i,p);}}else{var p=root.transform.position;p.x*=ratio;p.z*=ratio;root.transform.position=p;var s=root.transform.localScale;s.x*=ratio;s.z*=ratio;root.transform.localScale=s;}}
  m.goalLine=17.4f;m.halfWidth=8.7f;m.goalHalfWidth=3.045f;m.cornerRadius=3.625f;foreach(var t in m.trucks){t.acceleration=18;t.maxSpeed=11;t.reverseSpeed=6;t.turnDegrees=145;t.lateralGrip=.75f;t.rollingDrag=.12f;t.brakeDrag=8;t.impactMaxSpeed=14;t.body.mass=3;t.body.constraints=RigidbodyConstraints.FreezePositionY|RigidbodyConstraints.FreezeRotation;t.body.maxDepenetrationVelocity=3;t.ResetBody(m.SpawnPosition(t.side),m.SpawnRotation(t.side));}
  var contact=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>("Assets/TruckHockey/Materials/Truck contact.asset");contact.bounciness=.9f;contact.dynamicFriction=contact.staticFriction=.01f;contact.bounceCombine=PhysicsMaterialCombine.Maximum;EditorUtility.SetDirty(contact);
  foreach(var label in m.labels)if(label!=null)label.characterSize=.13f;var camera=UnityEngine.Object.FindAnyObjectByType<Camera>();camera.transform.position=new Vector3(0,28,-20);camera.transform.LookAt(Vector3.zero);var fit=camera.GetComponent<SportsCameraFit>();fit.worldWidth=48;fit.worldHeight=30;camera.orthographicSize=15;Debug.Log("TS_ICE_UPGRADE 34.8x17.4 grip=.75 drag=.12 restitution=.9 supplementalImpulse=0");
 }
 public static void UpgradeFront(){var scene=EditorSceneManager.OpenScene(SportsBuilder.FrontScene);var f=UnityEngine.Object.FindAnyObjectByType<SportsFrontEnd>();var page=f.pages[1].transform;var air=page.Find("AIR HOCKEY Sport Card");if(air==null){var clone=UnityEngine.Object.Instantiate(page.Find("HOCKEY Sport Card").gameObject,page);clone.name="AIR HOCKEY Sport Card";air=clone.transform;SportsUIAuthoring.Button(page,"AIR HOCKEY","airhockey",new Vector2(540,-225),new Vector2(305,80));}
  string[] names={"BILLIARDS","HOCKEY","BOWLING","AIR HOCKEY"};for(int i=0;i<4;i++){var card=page.Find(names[i]+" Sport Card");var rect=card.GetComponent<RectTransform>();rect.anchoredPosition=new Vector2(-540+i*360,-45);rect.sizeDelta=new Vector2(330,520);var title=card.Find("Sport").GetComponent<TMP_Text>();title.text=names[i];title.rectTransform.sizeDelta=new Vector2(305,70);title.fontSizeMax=32;title.fontSizeMin=26;var description=card.Find("Description").GetComponent<TMP_Text>();description.rectTransform.sizeDelta=new Vector2(305,175);description.fontSizeMax=21;description.fontSizeMin=18;if(i==1)description.text="Big rink • slippery 3v3.\nMomentum and major hits.\n0–6 humans or six AI.\nShared sticks supported.";if(i==3){description.text="Your truck is the mallet.\nEach stays in its half.\nCrisp rails • FIRST TO 7.\n1v1 human / AI.";var icon=card.Find("Rink icon");icon.GetComponent<UnityEngine.UI.Image>().color=new Color(.1f,.35f,.38f);icon.Find("Puck icon").GetComponent<UnityEngine.UI.Image>().color=Color.white;}foreach(var t in card.GetComponentsInChildren<RectTransform>())if(t.name.Contains("icon"))t.localScale=new Vector3(.68f,.85f,1);}
  foreach(var action in page.GetComponentsInChildren<SportsMenuAction>(true)){int i=action.action=="billiards"||action.action=="practice"?0:action.action=="hockey"?1:action.action=="bowling"?2:action.action=="airhockey"?3:-1;if(i<0)continue;var r=action.GetComponent<RectTransform>();r.anchoredPosition=new Vector2(-540+i*360,i==0?(action.action=="practice"?-270:-180):-225);r.sizeDelta=new Vector2(305,i==0?64:80);var text=action.button.normalTextObj;text.rectTransform.sizeDelta=r.sizeDelta-new Vector2(18,8);text.fontSizeMax=22;text.fontSizeMin=18;}
  f.pages[0].transform.Find("Collection").GetComponent<TMP_Text>().text="BILLIARDS  •  ICE HOCKEY  •  BOWLING  •  AIR HOCKEY\nFour ways to drive.";page.Find("Subtitle").GetComponent<TMP_Text>().text="Precision · slippery 3v3 · first-person bowling · 1v1 air hockey";var help=f.pages[2].transform.Find("Guidance").GetComponent<TMP_Text>();if(!help.text.Contains("AIR HOCKEY"))help.text+="\n\nAIR HOCKEY\nTruck mallets stay in their own halves. First to 7. Whole puck crossings count; own goals credit the opponent. The conceding player serves. Rematches alternate opening serve.";help.fontSizeMax=21;help.fontSizeMin=18;EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("TS_FOUR_SPORT_FRONT");if(System.IO.File.Exists(LWS.TruckWallball.Editor.WallballAuthoring.Scene))LWS.TruckWallball.Editor.WallballAuthoring.UpgradeFront();
 }
 public static void CreateUpdateBuild(){UpgradeHockey();LWS.TruckAirHockey.Editor.AirHockeyAuthoring.Create();UpgradeFront();SportsBuilder.Build();}
}
